UPDATE "app_settings"
SET "sitePages" = jsonb_set(
  COALESCE("sitePages", '{}'::jsonb),
  '{terms}',
  '{"slug":"terms","title":"Terms of Service","lastUpdated":"September 19, 2026","content":"Terms of Service\n\nEffective Date: September 19, 2026\n\nWelcome to WOLHOMES. These Terms of Service (\"Terms\") govern your use of our website, services, and the purchase of our products. By accessing or using our website, placing an order, or engaging with our brand, you agree to be bound by these Terms.\n\n1. General Conditions\n\nWOLHOMES operates as a direct manufacturer and global seller of handcrafted rugs and homewares. Our manufacturing and fulfillment operations are based out of our factory located at Devpurwa Road, Mirzapur, Uttar Pradesh, India.\n\nWe reserve the right to refuse service to anyone for any reason at any time.\n\n2. Products & Handcrafted Variations\n\nArtisanal Nature: Our products, particularly our Hand-Tufted and Hand-Knotted rugs, are handcrafted by master artisans. Minor variations in dye color, texture, weaving patterns, and exact sizing (typically within +/- 2-3%) are inherent characteristics of handmade products and are not considered defects.\n\nColor Accuracy: We make every effort to display product colors accurately on our website. However, actual colors may vary slightly depending on display settings and monitor calibrations.\n\n3. Custom & Made-to-Order Products\n\nFinal Sale: Custom and personalized rug orders are specially handcrafted to your individual specifications. As such, custom orders are non-returnable, non-exchangeable, and non-refundable once production has commenced.\n\nDefects or Errors: If a custom item arrives damaged, defective, or incorrectly made due to our manufacturing error, you must notify us within 48 hours of delivery with photographic evidence at info@wolhomes.com for a free replacement or resolution.\n\n4. Pricing, Payments, & Orders\n\nPrices for our products are subject to change without prior notice.\n\nWe accept major credit cards, PayPal, and authorized gift cards.\n\nWe reserve the right to cancel or refuse any order placed with us (e.g., in cases of suspected fraud or pricing errors). If an order is canceled after payment, a full refund will be issued to your original payment method.\n\n5. International Shipping, Duties, & Returns\n\nShipping: We offer global door-to-door shipping straight from our factory in Mirzapur, India.\n\nReturn Shipping & Customs (Buyer’s Responsibility): For eligible standard returns (excluding custom orders), the buyer is solely responsible for paying all return shipping charges, including any applicable customs duties, import taxes, and courier fees needed to deliver the package Delivered Duty Paid (DDP) to our factory in Mirzapur, India. Returns shipped with unpaid duties or postage-due will be rejected.\n\n6. Intellectual Property\n\nAll content on this website, including text, graphics, logos, images, rug designs, and software, is the property of WOLHOMES and is protected by applicable copyright, trademark, and intellectual property laws.\n\n7. Limitation of Liability\n\nWOLHOMES shall not be liable for any direct, indirect, incidental, punitive, or consequential damages resulting from your use of our website or any products purchased through our store, to the maximum extent permitted by law.\n\n8. Governing Law & Jurisdiction\n\nThese Terms of Service and any separate agreements whereby we provide you services shall be governed by and construed in accordance with the laws of India, with exclusive jurisdiction residing in the courts of Mirzapur, Uttar Pradesh, India.\n\n9. Contact Information\n\nQuestions about the Terms of Service should be sent to us at:\n\nEmail: info@wolhomes.com\n\nFactory Address: WOLHOMES, 575/2-C, Devpurwa Road, Mirzapur, Uttar Pradesh – 231001, India"}'::jsonb,
  true
),
"updatedAt" = CURRENT_TIMESTAMP
WHERE "id" = 'default';
